starter.javascript:
function hasDuplicates(items) {
  for (let i = 0; i < items.length; i++) {
    for (let j = 0; j < items.length; j++) {
      if (i !== j && items[i] === items[j]) {
        return true
      }
    }
  }
  return false
}

