solution.javascript:
function hasDuplicates(items) {
  return new Set(items).size !== items.length
}

solution.typescript:
function hasDuplicates(items: string[]): boolean {
  const seen = new Set<string>()
  for (const item of items) {
    if (seen.has(item)) return true
    seen.add(item)
  }
  return false
}
